-- ==========================================================================
-- SOA ITER CAMPUS: UNIFIED MULTI-FLOOR ACCESSIBILITY GRAPH (SUPABASE SCHEMA)
-- Supports Dijkstra multi-floor routing across Block C, D, E and outdoor paths
-- ==========================================================================

CREATE TABLE IF NOT EXISTS public.campus_nodes (
    id TEXT PRIMARY KEY,
    label TEXT NOT NULL,
    building_id TEXT NOT NULL,
    floor INTEGER NOT NULL DEFAULT 0,
    type TEXT NOT NULL,
    accessible BOOLEAN DEFAULT true,
    coord_x DOUBLE PRECISION DEFAULT 50,
    coord_y DOUBLE PRECISION DEFAULT 50,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.campus_edges (
    id SERIAL PRIMARY KEY,
    from_node TEXT REFERENCES public.campus_nodes(id) ON DELETE CASCADE,
    to_node TEXT REFERENCES public.campus_nodes(id) ON DELETE CASCADE,
    distance DOUBLE PRECISION NOT NULL,
    type TEXT NOT NULL,
    accessible BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Enable RLS & Read Policies
ALTER TABLE public.campus_nodes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campus_edges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read campus_nodes" ON public.campus_nodes FOR SELECT USING (true);
CREATE POLICY "Public read campus_edges" ON public.campus_edges FOR SELECT USING (true);
CREATE POLICY "Public insert campus_nodes" ON public.campus_nodes FOR ALL USING (true);
CREATE POLICY "Public insert campus_edges" ON public.campus_edges FOR ALL USING (true);

-- Clean previous rows
TRUNCATE TABLE public.campus_edges CASCADE;
TRUNCATE TABLE public.campus_nodes CASCADE;

